@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){ 
    Collection<V> vertices = resultMap.values(); 
    int size = vertices.size(); 
    Iterator<V> it = vertices.iterator(); 
    List<V> left = new ArrayList<>(); 
    List<V> right = new ArrayList<>(); 
    int idx = 0; 
    while(it.hasNext()){ 
        V v = it.next(); 
        if(idx < size/2) { 
            left.add(v); 
        } else { 
            right.add(v); 
        } 
        idx++; 
    } 
    // Ensure all vertices are in the graph 
    for(V v: vertices){ 
        target.addVertex(v); 
    } 
    // Add edges between every vertex in left and every vertex in right to form a complete bipartite graph 
    for(V u: left){ 
        for(V v: right){ 
            target.addEdge(u, v); 
        } 
    } 
}

