@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Set<V> vertices = new HashSet<>(resultMap.values());
    for (V v : vertices) {
        target.addVertex(v);
    }
    List<V> vertexList = new ArrayList<>(vertices);
    int size = vertexList.size();
    int mid = size / 2;
    for (int i = 0; i < mid; i++) {
        for (int j = mid; j < size; j++) {
            target.addEdge(vertexList.get(i), vertexList.get(j));
        }
    }
}

