@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    List<V> vertices=new ArrayList<>(resultMap.values());
    int n=vertices.size();
    int mid=n/2;
    for(int i=0;i<mid;i++){
        V u=vertices.get(i);
        target.addVertex(u);
        for(int j=mid;j<n;j++){
            V v=vertices.get(j);
            target.addVertex(v);
            target.addEdge(u,v);
        }
    }
}

