public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] actualArgs = pt.getActualTypeArguments();
    Class<?> raw = (Class<?>) pt.getRawType();

    // Build a mapping from type variables declared in targetType to concrete classes
    java.util.Map<TypeVariable<?>, Class<?>> typeVarAssigns = new java.util.HashMap<>();
    Class<?> current = targetType;
    while (current != null) {
        // Check superclass
        Type genericSuper = current.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) genericSuper;
            Class<?> superRaw = (Class<?>) superPT.getRawType();
            if (superRaw.equals(raw)) {
                TypeVariable<?>[] superVars = current.getTypeParameters();
                Type[] superArgs = superPT.getActualTypeArguments();
                for (int i = 0; i < superVars.length; i++) {
                    if (superArgs[i] instanceof Class) {
                        typeVarAssigns.put(superVars[i], (Class<?>) superArgs[i]);
                    }
                }
                break;
            }
        }
        // Check interfaces
        for (Type iface : current.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType ifacePT = (ParameterizedType) iface;
                Class<?> ifaceRaw = (Class<?>) ifacePT.getRawType();
                if (ifaceRaw.equals(raw)) {
                    TypeVariable<?>[] ifaceVars = current.getTypeParameters();
                    Type[] ifaceArgs = ifacePT.getActualTypeArguments();
                    for (int i = 0; i < ifaceVars.length; i++) {
                        if (ifaceArgs[i] instanceof Class) {
                            typeVarAssigns.put(ifaceVars[i], (Class<?>) ifaceArgs[i]);
                        }
                    }
                    break;
                }
            }
        }
        current = current.getSuperclass();
    }

    // Resolve type arguments
    Class<?>[] resolved = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type arg = actualArgs[i];
        if (arg instanceof Class) {
            resolved[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable) {
            Class<?> mapped = typeVarAssigns.get((TypeVariable<?>) arg);
            if (mapped == null) {
                return null; // cannot resolve
            }
            resolved[i] = mapped;
        } else if (arg instanceof ParameterizedType) {
            // return the raw type of the parameterized type
            Type rawArg = ((ParameterizedType) arg).getRawType();
            if (rawArg instanceof Class) {
                resolved[i] = (Class<?>) rawArg;
            } else {
                return null;
            }
        } else {
            return null; // unsupported type
        }
    }
    return resolved;
}

