public Mappings diffStructure(String tableName, Mappings mappings){
    // Fetch the current mapping for the table from the index
    Mappings current = esClient.getMapping(tableName);   // assume esClient is available

    // Prepare a map to hold the fields that are present in the current mapping
    // but missing from the input mappings.
    Map<String, Object> diffFields = new HashMap<>();

    // Iterate over every field in the current mapping.
    for (String field : current.fieldNames()) {
        // Skip the special _source field to avoid update conflicts.
        if ("_source".equals(field)) {
            continue;
        }
        // If the field is not defined in the input mappings, add it to the diff map.
        if (!mappings.fieldNames().contains(field)) {
            diffFields.put(field, current.getField(field));
        }
    }

    // Build and return a new Mappings instance containing only the diff fields.
    return Mappings.builder()
                   .fields(diffFields)
                   .build();
}

