public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Skip leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split by '/' to get individual segments
    String[] elems = path.split("/");
    for (String elem : elems) {
        if (elem.isEmpty()) {
            continue; // Skip empty segments caused by consecutive slashes
        }
        String value = elem;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(elem, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported, so rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        // Create PathSegmentImpl instance (assuming a constructor that takes the segment string)
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

