    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // ignore leading '/' if the path is absolute
    String path = rawPath;
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String seg = decode ? java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8)
                            : part;
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

