    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    int start = rawPath.startsWith("/") ? 1 : 0;
    int i = start;
    while (i <= rawPath.length()) {
        int slash = rawPath.indexOf('/', i);
        if (slash == -1) {
            slash = rawPath.length();
        }
        String seg = rawPath.substring(i, slash);
        if (decode) {
            seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8);
        }
        segments.add(new PathSegmentImpl(seg));
        i = slash + 1;
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    int start = 0;
    if (rawPath.charAt(0) == '/') {
        start = 1;
    }
    int i = start;
    int len = rawPath.length();
    while (i <= len) {
        if (i == len || rawPath.charAt(i) == '/') {
            String segRaw = rawPath.substring(start, i);
            String seg = segRaw;
            if (decode) {
                try {
                    seg = java.net.URLDecoder.decode(segRaw, java.nio.charset.StandardCharsets.UTF_8.name());
                } catch (Exception e) {
                    // keep the raw segment if decoding fails
                }
            }
            segments.add(new PathSegmentImpl(seg));
            start = i + 1;
        }
        i++;
    }
    return segments;
}

