    long result = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            throw new IOException("EOF while parsing varint");
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
