public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if (n % 2 == 0) n++;
    while (true) {
        boolean prime = true;
        if (n < 2) {
            prime = false;
        } else {
            for (int i = 3; i * i <= n; i += 2) {
                if (n % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) return n;
        n += 2;
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 5) {
        return 5;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // start with odd candidate
    }
    while (true) {
        boolean prime = true;
        if (candidate <= 1) {
            prime = false;
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 2; i <= sqrt; i++) {
                if (candidate % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
}

