public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2){
        return 2;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0){
        candidate++; // ensure odd
    }
    while (true){
        boolean isPrime = true;
        int limit = (int)Math.sqrt(candidate);
        for (int divisor = 3; divisor <= limit; divisor += 2){
            if (candidate % divisor == 0){
                isPrime = false;
                break;
            }
        }
        if (isPrime){
            return candidate;
        }
        candidate += 2; // next odd number
        if (candidate < 0){ // overflow
            return Integer.MAX_VALUE;
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if ((n & 1) == 0) n++; // start with an odd number if >2
    while (true) {
        int r = n;
        if (r <= 3) return r;
        if (r % 2 == 0 || r % 3 == 0) {
            // continue searching
        } else {
            boolean isPrime = true;
            for (int i = 5; i * i <= r; i += 6) {
                if (r % i == 0 || r % (i + 2) == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) return r;
        }
        n += 2; // skip even numbers
    }
}

