public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // unicode escape sequence \uXXXX
                    if (i + 6 <= length) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 5; // skip \uXXXX
                        } catch (NumberFormatException e) {
                            throw new Exception("Malformed Unicode escape: \\u" + hex);
                        }
                    } else {
                        throw new Exception("Incomplete Unicode escape sequence at end of string");
                    }
                    break;
                default:
                    // unknown escape, keep the character after the backslash
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

