protected int removeUnusedNodes(){
    // Assume 'root' refers to the top node of the category tree.
    int removedCount = 0;
    if (root == null) {
        return removedCount;
    }
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        java.util.List<Category> children = current.getChildren();
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            stack.push(child);
            if (!child.isActive()) {
                it.remove();
                removedCount++;
            }
        }
    }
    return removedCount;
}

