    stack.push(root);
    while (!stack.isEmpty()){
        Category current = stack.pop();
        java.util.List<Category> children = current.getChildren();
        if (children != null){
            java.util.List<Category> copy = new java.util.ArrayList<>(children);
            for (Category child : copy){
                if (!child.isActive()){
                    current.removeChild(child);
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    }
    return removed;
}

