private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop cannot be null");
    }
    OuterFaceCirculator circ = start.getOuterFaceCirculator();
    if (predicate.test(start)) {
        return circ;
    }
    Node curr = start;
    while (curr != stop) {
        curr = curr.getSuccessor(dir); // advance along outer face
        circ = curr.getOuterFaceCirculator();
        if (predicate.test(curr)) {
            return circ;
        }
    }
    return stop.getOuterFaceCirculator();
}

