private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node curr = start;
    while (!curr.equals(stop)) {
        if (predicate.test(curr)) {
            break;
        }
        circ = circ.next();
        curr = circ.getNode();
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    Node current = start;
    while(true){
        if(predicate.test(current)){
            return new OuterFaceCirculator(current);
        }
        if(current.equals(stop)){
            break;
        }
        // Advance to next node on the outer face in the specified direction
        current = dir >= 0 ? current.getNextOnOuterFace() : current.getPrevOnOuterFace();
        // If we looped back around without finding the stop node, break to avoid infinite loop
        if(current == null || current.equals(start)){
            break;
        }
    }
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
