protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        return null;
    }
    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return null;
    }
    List<V> vertices = new ArrayList<>();
    Set<V> visited = new HashSet<>();
    E firstEdge = edges.get(0);
    V start = graph.getEdgeSource(firstEdge);
    vewstart = graph.getEdgeTarget(firstEdge);
    vertices.add(start);
    visited.add(start);
    V current = start;
    for (E e : edges) {
        V s = graph.getEdgeSource(e);
        V t = graph.getEdgeTarget(e);
        V next = null;
        if (s.equals(current)) {
            next = t;
        } else if (t.equals(current)) {
            next = s;
        } else {
            // Edge does not continue the current path; try to start a new component
            continue;
        }
        if (!visited.contains(next)) {
            vertices.add(next);
            visited.add(next);
            current = next;
        }
    }
    double weight = 0.0;
    for (E e : edges) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphPath<V,E>() {
        @Override public Graph<V,E> getGraph() { return graph; }
        @Override public List<V> getVertexList() { return vertices; }
        @Override public List<E> getEdgeList() { return edges; }
        @Override public double getPathWeight() { return weight; }
    };
}

