    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // node was the first element
        head = next;
    } else {
        prev.next = next;
    }

    if (next != null) {
        next.prev = prev;
    } else {
        // node was the last element
        tail = prev;
    }

    // sever the links of the removed node
    node.prev = null;
    node.next = null;

    size--;
    return true;
}

