public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null || row < 0 || row >= table.getRowCount()) {
        return;
    }
    // Select the row
    table.setRowSelectionInterval(row, row);
    // Scroll the table to make the selected row visible
    Rectangle rect = table.getCellRect(row, 0, true);
    if (rect != null) {
        table.scrollRectToVisible(rect);
        // Ensure the viewport is updated
        Point viewPos = pane.getViewport().getViewPosition();
        if (viewPos == null) viewPos = new Point(0, 0);
        int y = rect.y;
        if (y < viewPos.y || y + rect.height > viewPos.y + pane.getViewport().getHeight()) {
            pane.getViewport().setViewPosition(new Point(viewPos.x, y));
        }
    }
    // Delay repaint until the GUI has processed layout changes
    SwingUtilities.invokeLater(() -> {
        pane.revalidate();
        pane.repaint();
        table.repaint();
    });
}

