    int pos = this.pos;
    if (this.buf.length - pos < 4) {
        int newSize = Math.max(this.buf.length << 1, pos + 4);
        this.buf = java.util.Arrays.copyOf(this.buf, newSize);
    }
    this.buf[pos]        = (byte) intValue;
    this.buf[pos + 1]    = (byte) (intValue >> 8);
    this.buf[pos + 2]    = (byte) (intValue >> 16);
    this.buf[pos + 3]    = (byte) (intValue >> 24);
    this.pos = pos + 4;
