private void pop(final String descriptor) {
    // Determine if this is a method descriptor (starts with '(')
    if (descriptor.length() > 0 && descriptor.charAt(0) == '(') {
        // Extract the argument part inside parentheses
        int closeParen = descriptor.indexOf(')');
        if (closeParen > 0) {
            String args = descriptor.substring(1, closeParen);
            int offset = 0;
            // Iterate over the argument types
            while (offset < args.length()) {
                char c = args.charAt(offset);
                // For object types the descriptor ends with ';'
                if (c == 'L') {
                    int semi = args.indexOf(';', offset);
                    if (semi == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    offset = semi + 1;
                } else {
                    // Primitive type (any single char descriptor)
                    offset++;
                }
                // Pop one abstract type from the output frame stack
                outputFrameStack.pop();
            }
        } else {
            // Invalid method descriptor
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
    } else {
        // Not a method descriptor => single type, just pop one
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int pos = 0;
    int length = descriptor.length();
    boolean isMethod = descriptor.charAt(0) == '(';
    if (isMethod) {
        pos = 1; // skip '('
        while (pos < length && descriptor.charAt(pos) != ')') {
            char ch = descriptor.charAt(pos);
            while (ch == '[') {
                pos++;
                ch = descriptor.charAt(pos);
            }
            if (ch == 'L') {
                int semicolon = descriptor.indexOf(';', pos);
                pos = semicolon + 1;
            } else {
                pos++;
            }
            outputFrameStack.pop();
        }
        // skip ')'
        if (pos < length && descriptor.charAt(pos) == ')') {
            pos++;
        }
    } else {
        while (pos < length) {
            char ch = descriptor.charAt(pos);
            while (ch == '[') {
                pos++;
                ch = descriptor.charAt(pos);
            }
            if (ch == 'L') {
                int semicolon = descriptor.indexOf(';', pos);
                pos = semicolon + 1;
            } else {
                pos++;
            }
            outputFrameStack.pop();
        }
    }
}

private void pop(final String descriptor) {
    // This method removes the number of abstract type slots from the output stack
    // that match the types described by the given descriptor.
    // If the descriptor is a method descriptor we need to pop its argument types.
    int start = descriptor.startsWith("(") ? 1 : 0;
    int end = descriptor.startsWith("(") ? descriptor.indexOf(')') : descriptor.length();
    for (int i = start; i < end; ) {
        char c = descriptor.charAt(i);
        // Handle array types, which may have multiple '[' prefixes.
        while (c == '[') {
            i++;
            c = descriptor.charAt(i);
        }
        // For object types, consume until the terminating ';'.
        if (c == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else {
            // Primitive type occupies one slot; advance one character.
            i++;
        }
        // Pop a value from the frame stack for each type encountered.
        outputStack.pop();
    }
}

