public static String applyRelativePath(String path, String relativePath) {
    java.nio.file.Path base = java.nio.file.Paths.get(path);
    java.nio.file.Path baseDir = base.getParent();
    if (baseDir == null) {
        baseDir = base;
    }
    java.nio.file.Path result = baseDir.resolve(relativePath).normalize();
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    // Preserve whether the original path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Split both paths into components, ignoring empty parts caused by leading/trailing slashes
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");
    // Use a list as a stack to process the path components
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();
    // Add the non-empty components of the base path
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Process the relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        sb.append(stack.get(i));
        if (i < stack.size() - 1) {
            sb.append("/");
        }
    }
    // If the resulting path is empty, return "." to represent the current directory
    return sb.length() == 0 ? "." : sb.toString();
}

