    if (relativePath==null||relativePath.isEmpty()){
        return path;
    }
    return java.nio.file.Paths.get(path).resolve(relativePath).normalize().toString();
}

public static String applyRelativePath(String path,String relativePath){
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    boolean leadingSlash = path.startsWith("/");
    for(String part : path.split("/")){
        if(part.isEmpty()||part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()) stack.removeLast();
        }else{
            stack.addLast(part);
        }
    }
    for(String part : relativePath.split("/")){
        if(part.isEmpty()||part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()) stack.removeLast();
        }else{
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if(leadingSlash) sb.append("/");
    boolean first = true;
    for(String seg : stack){
        if(!first) sb.append("/");
        sb.append(seg);
        first = false;
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return path;
    }
    // Determine if the path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Normalize multiple slashes by splitting and ignoring empty segments
    String[] pathParts = path.split("/");
    int pathLength = pathParts.length;
    // If path ends with "/", keep all segments; otherwise drop the last segment (file name)
    int lastIndex = (path.endsWith("/") || pathLength == 0) ? pathLength : pathLength - 1;
    java.util.List<String> baseSegments = new java.util.ArrayList<>();
    for (int i = 1; i < lastIndex; i++) { // skip possible leading empty segment
        if (!pathParts[i].isEmpty()) {
            baseSegments.add(pathParts[i]);
        }
    }
    // Process relative path components
    String[] relativeParts = relativePath.split("/");
    java.util.List<String> resultSegments = new java.util.ArrayList<>(baseSegments);
    for (String part : relativeParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!resultSegments.isEmpty()) {
                resultSegments.remove(resultSegments.size() - 1);
            }
            continue;
        }
        resultSegments.add(part);
    }
    // Build the resulting path
    String joined = String.join("/", resultSegments);
    if (isAbsolute) {
        return "/" + joined;
    }
    return joined.isEmpty() ? "." : joined;
}

