public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    int b;
    while (shift < 32 && (b = this.read()) != -1) {
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    return 0;
}

